async function navigateWithTransition(to: string, router: Router) {
  document.startViewTransition(async () => {
    const data = await fetchRouteData(to); // network call
    router.setRoute(to, data);
  });
}

function useSwipeBack(router: Router) {
  return (e: TouchEvent) => {
    if (e.changedTouches[0].clientX > 100) {
      navigateWithTransition('/back', router);
    }
  };
}
